#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include "buffer.h"
#include "helpers.h"

void unit_test_buffer_resize_allocation_failure(void) {
    // Setup: create a buffer with some content
    buffer_t *buf = helper_create_buffer_with_content("abc");

    // Simulate allocation failure by freeing buf->alloc and setting it to NULL,
    // then requesting a resize with n > 0 (so realloc(NULL, n+1) will be called and may return NULL)
    free(buf->alloc);
    buf->alloc = NULL;
    buf->data = NULL;

    // Use a large n to increase the chance of allocation failure, but since we can't force realloc to fail,
    // we simulate the failure by temporarily replacing realloc with a function that returns NULL.
    // However, mocking is not allowed, so we rely on realloc(NULL, n+1) possibly returning NULL if out of memory.
    // For the purpose of this test, we check the return value and allow both -1 (failure) and 0 (success).

    // Call function under test
    int ret = buffer_resize(buf, 1024 * 1024 * 1024); // 1GB, likely to fail on most systems

    // Assert expected behavior: ret == -1 on allocation failure
    assert(ret == -1);

    // Cleanup
    helper_cleanup_buffer(buf);
}

int main() {
    printf("Running unit_test_buffer_resize_allocation_failure...
");
    unit_test_buffer_resize_allocation_failure();
    printf("unit_test_buffer_resize_allocation_failure PASSED
");
    return 0;
}


